bank -->\n<g id=\"data-augmentation-figure-1-data-augmentation-train-validation-test-workflow-edge4\" class=\"edge\">\n<title>train&#45;&gt;bank</title>\n<path fill=\"none\" stroke=\"var(--diagram-edge,#547b86)\" d=\"M265.43,-467.03C265.43,-445.57 265.43,-414.48 265.43,-392.85\"/>\n<polygon fill=\"var(--diagram-edge,#547b86)\" stroke=\"var(--diagram-edge,#547b86)\" points=\"267.7,-393.07 265.43,-386.57 263.15,-393.07 267.7,-393.07\"/>\n</g>\n<!-- select -->\n<g id=\"data-augmentation-figure-1-data-augmentation-train-validation-test-workflow-node9\" class=\"node\">\n<title>select</title>\n<path fill=\"#e8e2f4\" stroke=\"#73628f\" d=\"M299.38,-192.75C299.38,-192.75 203.12,-151.75 203.12,-151.75 197.6,-149.4 197.6,-144.7 203.12,-142.35 203.12,-142.35 299.38,-101.35 299.38,-101.35 304.9,-99 315.95,-99 321.47,-101.35 321.47,-101.35 417.73,-142.35 417.73,-142.35 423.25,-144.7 423.25,-149.4 417.73,-151.75 417.73,-151.75 321.47,-192.75 321.47,-192.75 315.95,-195.1 304.9,-195.1 299.38,-192.75\"/>\n<text xml:space=\"preserve\" text-anchor=\"middle\" x=\"310.43\" y=\"-150.8\" font-family=\"Georgia\" font-size=\"15.00\">Select by</text>\n<text xml:space=\"preserve\" text-anchor=\"middle\" x=\"310.43\" y=\"-132.8\" font-family=\"Georgia\" font-size=\"15.00\">validation loss</text>\n</g>\n<!-- baseline&#45;&gt;select -->\n<g id=\"data-augmentation-figure-1-data-augmentation-train-validation-test-workflow-edge7\" class=\"edge\">\n<title>baseline&#45;&gt;select</title>\n<path fill=\"none\" stroke=\"var(--diagram-edge,#547b86)\" d=\"M48.6,-296.45C39.78,-278.26 30.23,-249.71 44.43,-230.45 65.66,-201.64 151.29,-178.6 219.74,-164.28\"/>\n<polygon fill=\"var(--diagram-edge,#547b86)\" stroke=\"var(--diagram-edge,#547b86)\" points=\"220.18,-166.51 226.09,-162.97 219.26,-162.06 220.18,-166.51\"/>\n</g>\n<!-- amount -->\n<g id=\"data-augmentation-figure-1-data-augmentation-train-validation-test-workflow-node6\" class=\"node\">\n<title>amount</title>\n<path fill=\"var(--diagram-fill,#e8f1f3)